function UIActivityMidFestivalBossDamageRewardDialog:InitHandler()
    SetButtonAction(self.BtnClose, Bind(self, self.OnBtnCloseHandler))
    SetButtonAction(self.Fuzzy, Bind(self, self.OnBtnCloseHandler))
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnOneKeyDrawHandler))
    ---@type ActivityMidFestivalBossComponent
    self._bossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalBossComponent)
    ---@type ActivityMidFestivalComponent
