function UIActivityMidFestivalBossDamageRewardDialog:InitData()
    if isNull(self._damageRewardList) then
        self._damageRewardList = self:GetDamageListVo()
    end

    self._historyMaxHurt = self._bossComponent:GetBossHomeDojo().historyMaxHurt
    self._isCanOneKeyDraw = self._bossComponent:IsCanOneKeyDrawReward()
    local homeDojo = self._activityComponent:GetHomeDojo()
    homeDojo:UpdateBossHurtRedPoint(self._isCanOneKeyDraw)
    self:RefreshUI()
end

function UIActivityMidFestivalBossDamageRewardDialog:GetDamageListVo()
    ---@type ActivityMidFestivalComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    local data = comp:GetRankRewards()
    return data
end
