function UIActivityMidFestivalBossDamageRewardDialog:InitItemByIndex(listView, index)
    local luaIndex = index + 1
    local cellData = self._damageRewardList[luaIndex]
    local cell = listView:NewListViewItem("Cell")
    ---@type UIActivityMidFestivalBossDamageRewardCell
    local scr = CfUtils.GetLuaScr(cell, "Game.Activity.MidFestival.BossDialog.UIActivityMidFestivalBossDamageRewardCell")
    scr:Refresh(cellData, self._historyMaxHurt)
    return cell
end

function UIActivityMidFestivalBossDamageRewardDialog:RefreshUI()
    CfUtils.SetActive(self.FontStyleButton, self._isCanOneKeyDraw)

    if not self.DamageLoopView.IsListViewInit then
        self.DamageLoopView:InitListView(#self._damageRewardList, Bind(self, self.InitItemByIndex))
    else
        GameUtils.ReloadData(self.DamageLoopView, #self._damageRewardList)
    end
end
